import java.util.HashMap;

public class AnagramCheck {

    public static void main(String[] args) {

        String s1 = "listen";
        String s2 = "silent";

        // দুটি হিসাব হুবহু মিললেই anagram
        boolean anagram = count(s1).equals(count(s2));

        System.out.println("Anagram: " + anagram);
    }

    // একটি string-এর কোন অক্ষর কতবার আছে
    static HashMap<Character, Integer> count(String s) {

        HashMap<Character, Integer> map = new HashMap<>();

        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            map.put(ch, map.getOrDefault(ch, 0) + 1);
        }
        return map;
    }
}

/*  Output:
    Anagram: true                                  */

import java.util.LinkedHashMap;
import java.util.Map;

public class FirstUnique {

    public static void main(String[] args) {

        String text = "swiss bank";

        // ধাপ ১ — প্রতিটি অক্ষর কতবার আছে
        LinkedHashMap<Character, Integer> freq = new LinkedHashMap<>();

        for (int i = 0; i < text.length(); i++) {

            char ch = text.charAt(i);

            if (ch == ' ') {
                continue;
            }

            freq.put(ch, freq.getOrDefault(ch, 0) + 1);
        }

        // ধাপ ২ — ঢোকার ক্রমে প্রথম যেটির গণনা 1
        char result = '-';

        for (Map.Entry<Character, Integer> e : freq.entrySet()) {

            if (e.getValue() == 1) {
                result = e.getKey();
                break;
            }
        }

        System.out.println("First unique: " + result);
    }
}

